// A stand-in for fetch: the sandbox has no network. It returns a promise
// of a response with ok, status and json(), after a short delay.
function fakeFetch(url) {
  const routes = {
    "/api/rates": { EUR: 0.86, GBP: 0.75 },
    "/api/categories": [{ name: "food" }, { name: "travel" }, { name: "fun" }],
  };
  return new Promise((resolve) => {
    setTimeout(() => {
      const ok = url in routes;
      const body = ok ? routes[url] : { error: "Not found" };
      resolve({ ok, status: ok ? 200 : 404, json: async () => body });
    }, 30);
  });
}

async function getJson(url) {
  const response = await fakeFetch(url);
  if (!response.ok) {
    throw new Error(`HTTP ${response.status} for ${url}`);
  }
  return response.json();
}

async function loadCategoryNames() {
  const categories = await getJson("/api/categories");
  return categories.map((c) => c.name);
}

async function toEuroCents(cents) {
  const rates = await getJson("/api/rates");
  return Math.round(cents * rates.EUR);
}

async function safeGetJson(url, fallback) {
  try {
    return await getJson(url);
  } catch {
    return fallback;
  }
}

loadCategoryNames().then((names) => console.log(names));

